    def make_step(cid):  #899 (line in Coconut source)
        lits, rule, parents = info[cid]  #900 (line in Coconut source)
        return ProofStep(renumber[cid], clause_formula(lits), rule, (tuple)((map)(renumber.__getitem__, parents)))  #901 (line in Coconut source)

