    original_names = set(used)  #950 (line in Coconut source)
    labeled = [(p, "premise {_coconut_format_0}".format(_coconut_format_0=(i))) for i, p in enumerate(closed_premises, 1)] + [(Not(closed_conclusion), "negated conclusion"),]  #951 (line in Coconut source)
